  "tool.summary.background_updated": { "zh-CN": "后台任务已更新", en: "Background task updated" },
  "tool.summary.background_started": { "zh-CN": "后台任务已启动", en: "Background task started" },
  "tool.task.background_description": {
    "zh-CN":
      "后台模式：background=true 会异步启动子代理并立即返回。默认是前台模式；需要在继续前获得结果时使用前台。后台模式仅适用于可在你继续其他工作时独立运行的任务。任务完成后会自动通知你。",
    en: "Background mode: background=true launches the subagent asynchronously and returns immediately. Foreground is the default; use it when you need the result before continuing. Use background only for independent work that can run while you continue elsewhere. You will be notified automatically when it finishes.",
  },
  "tool.task.background_started": {
    "zh-CN":
      "任务正在后台运行，完成后会自动通知你。不要休眠、轮询进度、询问任务状态或重复此任务的工作；请处理不重叠的任务，或简要告知用户你启动了什么后结束回复。",
    en: "The task is working in the background. You will be notified automatically when it finishes. Do not sleep, poll for progress, ask the task for status, or duplicate this task's work. Work on non-overlapping tasks, or briefly tell the user what you launched and end your response.",
  },
  "tool.task.background_updated": {
    "zh-CN":
      "已向正在运行的后台任务发送附加上下文。任务仍在后台运行，完成后会自动通知你。不要休眠、轮询进度、询问任务状态或重复此任务的工作；请处理不重叠的任务，或简要告知用户你发送了什么后结束回复。",
    en: "Additional context sent to the running background task. The task is still working in the background. You will be notified automatically when it finishes. Do not sleep, poll for progress, ask the task for status, or duplicate this task's work. Work on non-overlapping tasks, or briefly tell the user what you sent and end your response.",
  },
