    "zh-CN":
      "使用主机用户的文件系统、进程和网络权限执行一条 shell 命令。活动 Location 是默认工作目录；相对 workdir 相对于该 Location。外部 workdir 需要 external_directory 审批；命令参数路径警告仅供参考。超时时间单位为毫秒，并使用配置的 shell。",
    en: "Execute one shell command string with the host user's filesystem, process, and network authority. The active Location is the default working directory. Relative workdir values resolve from that Location. External workdir values require external_directory approval; best-effort command-argument path warnings are advisory only. Timeout values are milliseconds (default and maximum are configured by the runtime). Uses the configured shell when set; otherwise uses /bin/sh on POSIX and COMSPEC or cmd.exe on Windows.",
