  "tool.error.fetched_file_type": {
    "zh-CN": "不支持获取到的文件内容类型：{{mime}}",
    en: "Unsupported fetched file content type: {{mime}}",
  },
  "tool.error.fetch": { "zh-CN": "无法获取 {{url}}", en: "Unable to fetch {{url}}" },
  "tool.description.core_websearch": {
    "zh-CN":
      "使用会话的本地网页搜索提供商搜索网页。用于获取知识截止日期之后的当前信息。\n\n这是由 Exa 或 Parallel 支持、独立于提供商的本地工具。提供商托管的网页搜索工具是独立的，并在模型提供商处执行。\n\n可选控制项支持结果数量、实时抓取（'fallback' 或 'preferred'）、搜索类型（'auto'、'fast' 或 'deep'）以及最大上下文字符数。\n\n当前年份是 {{year}}。搜索近期信息或当前事件时请使用该年份。",
    en: "Search the web using the session's local web search provider. Use this for current information beyond knowledge cutoff.\n\nThis is a provider-independent local tool backed by Exa or Parallel. Provider-hosted web search tools are separate and execute at the model provider.\n\nOptional controls support result count, live crawling ('fallback' or 'preferred'), search type ('auto', 'fast', or 'deep'), and maximum context characters.\n\nThe current year is {{year}}. Use this year when searching for recent information or current events.",
  },
  "tool.error.search_response_too_large": {
    "zh-CN": "{{tool}} 响应超过 {{max}} 字节",
    en: "{{tool}} response exceeded {{max}} bytes",
  },
  "tool.error.search_timeout": { "zh-CN": "{{tool}} 请求超时", en: "{{tool}} request timed out" },
  "tool.error.websearch": {
    "zh-CN": "无法在网页中搜索 {{query}}",
    en: "Unable to search the web for {{query}}",
  },
  "tool.description.core_question": {
    "zh-CN":
      "执行过程中需要向用户提问时使用此工具。它允许你：\n1. 收集用户偏好或要求\n2. 澄清含糊指令\n3. 在工作过程中获取实现选择的决定\n4. 向用户提供方向选择。\n\n使用说明：\n- 启用 `custom`（默认）时，会自动添加“输入你自己的答案”选项；不要加入“其他”或兜底选项\n- 答案以标签数组返回；设置 `multiple: true` 可允许多选\n- 如果你推荐某个特定选项，请将其放在列表首位，并在标签末尾添加“（推荐）”",
    en: 'Use this tool when you need to ask the user questions during execution. This allows you to:\n1. Gather user preferences or requirements\n2. Clarify ambiguous instructions\n3. Get decisions on implementation choices as you work\n4. Offer choices to the user about what direction to take.\n\nUsage notes:\n- When `custom` is enabled (default), a "Type your own answer" option is added automatically; don\'t include "Other" or catch-all options\n- Answers are returned as arrays of labels; set `multiple: true` to allow selecting more than one\n- If you recommend a specific option, make that the first option in the list and add "(Recommended)" at the end of the label',
  },
