export type MessageKey = keyof typeof messages
export type MessageParameters = Record<string, string | number | undefined>

export function builtinToolDisplayName(language: Language | undefined, tool: string) {
  const key = `tool.name.${tool}`
  if (!Object.prototype.hasOwnProperty.call(messages, key)) return undefined
  return t(language, key as MessageKey)
}

export function resolveLanguage(input: unknown): Language {
  return input === "en" ? "en" : "zh-CN"
}

export function t(language: Language | undefined, key: MessageKey, parameters: MessageParameters = {}) {
  return messages[key][resolveLanguage(language)].replace(/{{(\w+)}}/g, (_, name: string) =>
    String(parameters[name] ?? ""),
  )
}

export function zh(key: MessageKey, parameters: MessageParameters = {}) {
  return t("zh-CN", key, parameters)
}

const knownTranslationTemplates = new Map<Language, Array<{ key: MessageKey; names: string[]; pattern: RegExp }>>()

export function localizeKnownText(language: Language | undefined, input: string) {
  const target = resolveLanguage(language)
  const cached = knownTranslationTemplates.get(target)
  const templates =
    cached ??
    Object.entries(messages).map(([key, value]) => {
      const source = value[target === "en" ? "zh-CN" : "en"]
      const names = [...source.matchAll(/{{(\w+)}}/g)].map((match) => match[1]!)
      return {
        key: key as MessageKey,
        names,
        pattern: new RegExp(
          `^${source
            .split(/{{\w+}}/g)
            .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
            .join("(.+?)")}$`,
        ),
      }
    })
  if (!cached) knownTranslationTemplates.set(target, templates)
  for (const template of templates) {
    const match = template.pattern.exec(input)
    if (!match) continue
    return t(target, template.key, Object.fromEntries(template.names.map((name, index) => [name, match[index + 1]])))
  }
  return input
}

export function formatDate(language: Language | undefined, input: number | Date, options?: Intl.DateTimeFormatOptions) {
  return new Intl.DateTimeFormat(resolveLanguage(language), options).format(input)
}

export function formatNumber(language: Language | undefined, input: number, options?: Intl.NumberFormatOptions) {
  return new Intl.NumberFormat(resolveLanguage(language), options).format(input)
}
